import React, { useState, useRef } from 'react';
import { CharacterData, Faction } from '../types';
import { NPC_VOLUMES } from '../constants';
import { Button } from './Shared';
import { User as UserIcon, Skull, Sun, Moon, Ghost, Plus, ShieldCheck, Sword, Wand2, Crown, Link as LinkIcon, Terminal, Settings, ChevronLeft, ChevronRight, ChevronDown, Calendar, Upload } from 'lucide-react';
import { useAuth } from '../../../context/AuthContext';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';

interface Props {
  characters: CharacterData[];
  onSelect: (id: string) => void;
  onCreate: () => void;
  onImport: (file: File) => void;
  onOpenSettings?: () => void;
  onOpenTraining?: () => void;
}

const Roster: React.FC<Props> = ({ characters, onSelect, onCreate, onImport, onOpenSettings, onOpenTraining }) => {
  const { isAdmin, user } = useAuth();
  /* [DIALECT] */ const { t, handleLetterClick, handleSlashClick, isInputMode, inputBuffer, isBloodMode, trackTabChange } = useDialect();
  const importFileRef = useRef<HTMLInputElement>(null);

  // Lazy initialize state from LocalStorage
  const [activeTab, setActiveTab] = useState<Faction>(() => {
      return (localStorage.getItem('roster_active_tab') as Faction) || Faction.LIGHT;
  });

  const [npcVolume, setNpcVolume] = useState<string>(() => {
      return localStorage.getItem('roster_npc_volume') || NPC_VOLUMES[0];
  });

  // Track tabs for secrets & persistence
  const handleTabChange = (faction: Faction) => {
      setActiveTab(faction);
      trackTabChange(faction);
      localStorage.setItem('roster_active_tab', faction);
  };

  const handleNpcVolumeChange = (vol: string) => {
      setNpcVolume(vol);
      localStorage.setItem('roster_npc_volume', vol);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          onImport(file);
          if (importFileRef.current) importFileRef.current.value = "";
      }
  };

  // Tab ordering for navigation
  const tabs = [Faction.LIGHT, Faction.DARK, Faction.GRAVEYARD, Faction.NPC];

  const handleNextTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx + 1) % tabs.length]);
  };

  const handlePrevTab = () => {
      const idx = tabs.indexOf(activeTab);
      handleTabChange(tabs[(idx - 1 + tabs.length) % tabs.length]);
  };

  const filtered = characters.filter(c => {
    if (!c.profile) return false;

    const isCompanion = c.profile.faction === Faction.NPC && c.profile.npc_volume === "Спутники и Рабы";
    if (c.meta.master_id && !isCompanion) return false;

    if (c.profile.faction !== activeTab) return false;
    if (activeTab === Faction.NPC && c.profile.npc_volume !== npcVolume) return false;
    return true;
  });

  // --- Theme Logic ---
  const getTheme = (f: Faction) => {
    // Blood Mode Override
    if (isBloodMode) {
        return {
            tab: "text-red-600 drop-shadow-[0_0_8px_rgba(220,38,38,0.8)] animate-pulse",
            border: "border-red-600/60",
            glow: "shadow-[0_0_30px_rgba(220,38,38,0.3)]",
            bg: "bg-red-950/40",
            text: "text-red-200",
            glowColor: "from-red-900/30"
        };
    }

    switch (f) {
      case Faction.LIGHT: 
        return {
          tab: "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)]",
          border: "border-amber-500/30",
          glow: "shadow-[0_0_20px_rgba(251,191,36,0.1)]",
          bg: "bg-amber-950/20",
          text: "text-amber-100",
          // BRIGHTER LIGHT AMBIENCE
          glowColor: "from-amber-200/15" 
        };
      case Faction.DARK: 
        return {
          tab: "text-violet-400 drop-shadow-[0_0_8px_rgba(139,92,246,0.5)]",
          border: "border-violet-500/40",
          glow: "shadow-[0_0_20px_rgba(139,92,246,0.2)]",
          bg: "bg-violet-950/30",
          text: "text-violet-100",
          glowColor: "from-violet-900/20"
        };
      case Faction.NPC: 
        return {
          tab: "text-red-500 drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]",
          border: "border-red-500/30",
          glow: "shadow-[0_0_20px_rgba(239,68,68,0.1)]",
          bg: "bg-red-950/20",
          text: "text-red-100",
          glowColor: "from-red-900/20"
        };
      case Faction.GRAVEYARD: 
        return {
          tab: "text-slate-400 drop-shadow-[0_0_8px_rgba(148,163,184,0.5)]",
          border: "border-slate-500/30",
          glow: "shadow-[0_0_10px_rgba(148,163,184,0.1)]",
          bg: "bg-slate-900/20",
          text: "text-slate-300",
          glowColor: "from-slate-800/30"
        };
      default: 
        return { tab: "", border: "border-slate-700", glow: "", bg: "", text: "", glowColor: "from-slate-900/10" };
    }
  };

  const theme = getTheme(activeTab);

  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const getLabelKey = (faction: Faction) => 
      faction === Faction.LIGHT ? 'fac_light' : 
      faction === Faction.DARK ? 'fac_dark' :
      faction === Faction.NPC ? 'fac_npc' : 'fac_graveyard';

  const TabButton = ({ faction, icon: Icon }: { faction: Faction, icon: any }) => {
    const isActive = activeTab === faction;
    const labelKey = getLabelKey(faction);
    const localTheme = getTheme(faction);

    return (
      <button
        onClick={() => handleTabChange(faction)}
        className={`relative flex items-center gap-2 px-6 py-3 font-serif font-bold uppercase tracking-widest text-[10px] md:text-xs transition-all whitespace-nowrap flex-shrink-0 ${
          isActive ? `${localTheme.tab} bg-white/5` : "text-slate-600 hover:text-slate-400 hover:bg-white/5"
        }`}
      >
        <Icon size={16} className={isBloodMode ? "text-red-500" : ""} />
        {t(labelKey, faction)}
        {isActive && (
           <div className={`absolute bottom-0 left-0 w-full h-0.5 bg-current shadow-[0_0_10px_currentColor]`}></div>
        )}
      </button>
    );
  };

  const renderInteractiveTitle = (text: string) => {
    return text.split('').map((char, i) => (
      <span 
        key={i} 
        onClick={(e) => {
           e.stopPropagation();
           handleLetterClick(char);
        }}
        className={`transition-colors cursor-pointer select-none active:scale-90 inline-block ${isBloodMode ? 'hover:text-red-500' : 'hover:text-violet-400'}`}
      >
        {char}
      </span>
    ));
  };

  // Main Background Image
  const rosterBg = "https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/character-roster-bg.jpg"; 

  return (
    <div className={`relative flex flex-col w-full h-[calc(100dvh-3rem)] md:h-[100dvh] overflow-hidden bg-transparent transition-all duration-1000 ${isBloodMode ? 'grayscale-[0.2] sepia-[0.3] hue-rotate-[-30deg]' : ''}`}>

      {/* Background Image Layer */}
      <div 
        className="absolute inset-0 bg-cover bg-center opacity-40 z-0 pointer-events-none mix-blend-screen"
        style={{ 
            backgroundImage: `url(${rosterBg})`,
            filter: 'contrast(1.2) brightness(0.6)' 
        }} 
      ></div>

      {/* Dark Overlay Gradient to ensure text legibility */}
      <div className="absolute inset-0 bg-gradient-to-br from-slate-950 via-slate-950/80 to-slate-950 pointer-events-none z-0"></div>

      {/* DYNAMIC ATMOSPHERIC LIGHTING LAYERS */}
      {/* Top ambient glow based on faction */}
      <div className={`fixed top-0 left-0 right-0 h-32 bg-gradient-to-b ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>
      {/* Bottom ambient glow based on faction */}
      <div className={`fixed bottom-0 left-0 right-0 h-32 bg-gradient-to-t ${theme.glowColor} to-transparent pointer-events-none z-0 transition-all duration-700 gpu-accelerated`}></div>

      {/* Scrollable Content Layer */}
      <div className="flex-1 overflow-y-auto custom-scrollbar px-4 md:px-12 pt-4 md:pt-8 pb-32 w-full relative z-10">

            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4 border-b border-white/10 pb-6">
                <div>
                    <h1 className={`text-4xl md:text-6xl font-gothic font-normal text-transparent bg-clip-text bg-gradient-to-r tracking-[0.05em] uppercase flex items-center gap-4 drop-shadow-[0_0_15px_rgba(255,255,255,0.1)] ${isBloodMode ? 'from-red-300 via-red-100 to-red-500' : 'from-slate-200 via-white to-slate-400'}`}>
                        <div className="flex items-center gap-2">
                            <span className="flex">{renderInteractiveTitle(t('app_title_1', 'Летопись'))}</span> 
                            <span 
                            onClick={(e) => {
                                e.stopPropagation();
                                handleSlashClick();
                            }}
                            className={`px-1 rounded-sm ${isBloodMode ? 'text-red-600' : 'text-violet-500'} cursor-pointer hover:brightness-150 transition-colors select-none active:scale-90 inline-block`}
                            >
                            //
                            </span> 
                            <span className="flex">{renderInteractiveTitle(t('app_title_2', 'Душ'))}</span>
                        </div>
                    </h1>
                    <p className={`font-sans text-sm mt-2 max-w-xl ${isBloodMode ? 'text-red-400/70' : 'text-slate-500'}`}>
                       Реестр сущностей, героев и монстров. Управление характеристиками и судьбами.
                    </p>
                </div>

                {/* Actions Panel */}
                <div className="flex items-center gap-3">
                    {/* Public Training Log Button */}
                    {onOpenTraining && (
                        <Button onClick={onOpenTraining} size="sm" variant="ghost" className="text-slate-400 hover:text-white border border-slate-700/50">
                            <Calendar size={16} /> Журнал Тренировок
                        </Button>
                    )}

                    {/* Admin Settings Button */}
                    {isAdmin && onOpenSettings && (
                        <Button onClick={onOpenSettings} size="sm" variant="ghost" className="text-slate-400 hover:text-white border border-slate-700/50">
                            <Settings size={16} />
                        </Button>
                    )}

                    {/* User Actions (Create / Import) */}
                    {(isAdmin || user) && (
                        <>
                            <input 
                                type="file" 
                                ref={importFileRef} 
                                className="hidden" 
                                accept=".json" 
                                onChange={handleFileChange} 
                            />
                            <Button 
                                onClick={() => importFileRef.current?.click()} 
                                size="sm" 
                                variant="secondary" 
                                className="text-slate-300 border-slate-600 hover:bg-slate-800"
                            >
                                <Upload size={14} /> Импорт
                            </Button>

                            <Button 
                                onClick={onCreate} 
                                size="sm" 
                                className="bg-violet-600/80 border-violet-500 hover:bg-violet-500 text-white shadow-[0_0_15px_rgba(139,92,246,0.3)]"
                            >
                                <Plus size={14} /> {t('btn_new', 'Новый')}
                            </Button>
                        </>
                    )}
                </div>
            </div>

            {/* Tabs - Desktop */}
            <div className="hidden md:flex border-b border-white/5 mb-8">
                <TabButton faction={Faction.LIGHT} icon={Sun} />
                <TabButton faction={Faction.DARK} icon={Moon} />
                <TabButton faction={Faction.GRAVEYARD} icon={Skull} />
                <TabButton faction={Faction.NPC} icon={Ghost} />
            </div>

            {/* Tabs - Mobile */}
            <div className="md:hidden flex items-center justify-between border-b border-white/5 pb-4 mb-4">
                <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronLeft size={24} />
                </button>
                <div className={`font-serif font-bold uppercase tracking-widest text-lg ${theme.tab}`}>
                    {t(getLabelKey(activeTab), activeTab)}
                </div>
                <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronRight size={24} />
                </button>
            </div>

            {/* Content Area */}
            <div className="relative min-h-[500px]">

                {activeTab === Faction.NPC && (
                <div className="mb-6">
                    <label className="text-[10px] uppercase font-bold text-slate-500 mb-2 block tracking-widest font-serif">{t('lbl_npc_vol', "Архив Бестиария")}</label>
                    <div className="relative max-w-md">
                        <select 
                        value={npcVolume} 
                        onChange={(e) => handleNpcVolumeChange(e.target.value)}
                        className={`bg-slate-900/50 border text-slate-200 text-sm rounded-lg w-full p-3 outline-none appearance-none font-sans ${isBloodMode ? 'border-red-900/50 focus:border-red-500' : 'border-slate-700 focus:border-violet-500 focus:shadow-[0_0_15px_rgba(139,92,246,0.2)]'}`}
                        >
                        {NPC_VOLUMES.map(v => <option key={v} value={v} className="bg-slate-900 text-slate-200">{getVolumeLabel(v)}</option>)}
                        </select>
                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={16} />
                    </div>
                </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
                {filtered.map(char => (
                    <div 
                        key={char.id} 
                        onClick={() => onSelect(char.id)}
                        className={`
                            group relative overflow-hidden rounded-xl cursor-pointer transition-all duration-300
                            bg-slate-900/40 backdrop-blur-md border border-white/5 hover:-translate-y-1
                            ${theme.border} ${theme.glow}
                            content-visibility-auto
                        `}
                    >
                        {/* Card Background Glow */}
                        <div className={`absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 bg-gradient-to-br ${theme.bg} to-transparent pointer-events-none`}></div>

                        <div className="p-4 relative z-10 flex flex-col h-full gap-3">

                            {/* Header: Avatar & Name */}
                            <div className="flex items-start gap-3">
                                <div className="relative shrink-0">
                                    <div className="w-12 h-12 rounded-lg bg-black/50 border border-white/10 overflow-hidden flex items-center justify-center group-hover:border-white/30 transition-colors">
                                        {char.meta.avatar_url ? (
                                            <img src={char.meta.avatar_url} className="w-full h-full object-cover" loading="lazy" decoding="async" />
                                        ) : (
                                            <UserIcon size={20} className="text-slate-600" />
                                        )}
                                    </div>
                                    <div className={`absolute -bottom-1 -right-1 bg-black text-white text-[9px] font-bold px-1.5 rounded border ${isBloodMode ? 'border-red-900' : 'border-white/20'}`}>
                                        {char.profile.level}
                                    </div>
                                </div>

                                <div className="flex-1 min-w-0">
                                    <h3 className={`font-fantasy font-bold text-lg leading-tight truncate ${theme.text} group-hover:text-white transition-colors`}>
                                        {char.profile.name}
                                    </h3>

                                    {/* Subtext: Save Status */}
                                    <div className="flex items-center gap-2 mt-1">
                                        {char.profile.faction === Faction.GRAVEYARD ? (
                                            <span className="text-[10px] text-slate-500 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {char.meta.save_status_reason || t('meta_death_unknown', "Почил")}
                                            </span>
                                        ) : char.meta.save_status ? (
                                            <span className={`text-[10px] uppercase tracking-wide flex items-center gap-1 ${isBloodMode ? 'text-red-400' : 'text-emerald-500/80'}`}>
                                                <ShieldCheck size={10} /> {t('meta_save_ok', 'Сейв есть')}
                                            </span>
                                        ) : (
                                            <span className="text-[10px] text-red-500/80 uppercase tracking-wide flex items-center gap-1">
                                                <Skull size={10} /> {t('meta_save_lost', 'Без сейва')}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Master Link */}
                            {char.meta.master_id && char.profile.faction === Faction.NPC && (
                                <div className="text-[10px] bg-white/5 rounded px-2 py-1 text-violet-300 border border-violet-500/20 flex items-center gap-2">
                                    <LinkIcon size={10} /> 
                                    <span>{t('lbl_linked', 'Связан узами')}</span>
                                </div>
                            )}

                            {/* Stats Grid - Minimalist */}
                            <div className="grid grid-cols-3 gap-1 mt-auto pt-2 border-t border-white/5">
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Sword size={10} className="text-red-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.phys}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Wand2 size={10} className="text-blue-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.magic}</span>
                                </div>
                                <div className="flex flex-col items-center p-1 bg-black/20 rounded">
                                    <Crown size={10} className="text-purple-400 mb-0.5" />
                                    <span className="text-xs font-mono font-bold text-slate-300">{char.stats.unique}</span>
                                </div>
                            </div>

                            {/* Equipment Line */}
                            <div className="text-[9px] text-slate-500 truncate h-4">
                                {char.equipment.wearable.filter(w => w.is_equipped).map(w => w.name).join(", ") || ""}
                            </div>
                        </div>
                    </div>
                ))}

                {filtered.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-600 border-2 border-dashed border-slate-800 rounded-xl bg-slate-900/20">
                        <Ghost size={48} className="mb-4 opacity-20"/>
                        <span className="text-sm font-bold uppercase tracking-widest font-serif">{t('msg_empty', 'Лишь ветер гуляет')}</span>
                    </div>
                )}
                </div>
            </div>
      </div>

      {/* [DIALECT] Easter Egg Input Window */}
      {isInputMode && (
          <div className="fixed inset-0 md:absolute md:inset-auto md:bottom-4 md:left-1/2 md:-translate-x-1/2 md:bottom-8 z-[100] animate-fadeIn flex items-center justify-center pointer-events-none p-4">
              <div className="bg-black/95 border border-violet-900 rounded-lg p-4 shadow-[0_0_40px_rgba(139,92,246,0.4)] backdrop-blur-md pointer-events-auto w-full max-w-sm relative">
                <div className="flex items-center gap-2 mb-2 justify-between">
                  <div className="flex items-center gap-2">
                      <Terminal size={14} className="text-violet-500 animate-pulse"/>
                      <span className="text-[10px] font-mono text-violet-300 uppercase tracking-widest">Input Sequence</span>
                  </div>
                </div>
                <div className="bg-slate-950 border border-slate-800 rounded p-3 min-h-[3rem] flex items-center justify-center overflow-hidden">
                    <span className="font-serif text-sm md:text-base text-violet-400 tracking-[0.1em] md:tracking-[0.2em] uppercase drop-shadow-[0_0_5px_rgba(167,139,250,0.8)] break-all text-center">
                      {inputBuffer || <span className="opacity-20">_ _ _ _ _ _</span>}
                    </span>
                </div>
                <div className="text-center mt-2">
                    <span className="text-[9px] text-slate-600 uppercase font-bold tracking-widest">Tap title letters & slashes</span>
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Roster;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_CHARACTER, DEFAULT_INJURIES, DEFAULT_TIME_UNITS } from './constants';
import { CharacterData, InjuryDefinition, TimeUnit, Faction } from './types';
import * as SupabaseService from './utils/supabaseService';
import Roster from './components/Roster';
import SheetHeader from './components/SheetHeader';
import TabEquipment from './components/TabEquipment';
import TabAbilities from './components/TabAbilities';
import TabPassives from './components/TabPassives';
import TabDebuffs from './components/TabDebuffs';
import TabUnits from './components/TabUnits';
import TabMedCard from './components/TabMedCard';
import GlobalSettingsModal from './components/GlobalSettingsModal';
import { TagHintsModal } from './components/TagHintsModal';
import { Button } from './components/Shared';
import { Save, ChevronLeft, ChevronRight, Edit3, Trash2, RotateCcw, Settings, BookOpen, Calculator, ScrollText, Loader2, Tag } from 'lucide-react';
import { DialectProvider, useDialect } from './dialect_module/DialectContext';
import { UIProvider, useUI } from './context/UIContext';
import { TrainingPage } from './pages/TrainingPage';
import { useAuth } from '../../context/AuthContext';

export type DisplayMode = 'lore' | 'mech';

interface RosterModuleProps {
  isAdmin?: boolean;
}

const RosterContent: React.FC<RosterModuleProps> = ({ isAdmin = false }) => {
  const { toggleDialect, isOldSlavonic, isDialectUnlocked, t } = useDialect();
  const { showAlert, showConfirm } = useUI();
  const { user } = useAuth();

  const [view, setView] = useState<'roster' | 'sheet' | 'training'>('roster');
  const [characters, setCharacters] = useState<CharacterData[]>([]);
  const [rosterList, setRosterList] = useState<CharacterData[]>([]);
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const [charStack, setCharStack] = useState<string[]>([]);

  const [displayMode, setDisplayMode] = useState<DisplayMode>('lore');
  const [isEditMode, setIsEditMode] = useState(false);
  const [activeTab, setActiveTab] = useState<'equipment' | 'abilities' | 'passives' | 'debuffs' | 'units' | 'medcard'>('equipment');

  const [triggersMap, setTriggersMap] = useState<Record<string, string>>({});
  const [injuryDefinitions, setInjuryDefinitions] = useState<InjuryDefinition[]>(DEFAULT_INJURIES);
  const [timeUnits, setTimeUnits] = useState<TimeUnit[]>(DEFAULT_TIME_UNITS);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isTagHintsOpen, setIsTagHintsOpen] = useState(false);

  const SHEET_TABS = useMemo(() => [
    { id: 'equipment', label: t('tab_eq', 'Снаряжение') },
    { id: 'abilities', label: t('tab_ab', 'Способности') },
    { id: 'passives', label: t('tab_ps', 'Пассивки') },
    { id: 'debuffs', label: t('tab_db', 'Дебаффы') },
    { id: 'units', label: t('tab_un', 'Юниты') },
    { id: 'medcard', label: t('tab_mc', 'Мед.Карта') },
  ], [t]);

  const initRef = useRef(false);

  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;
    const init = async () => {
      setIsLoadingData(true);
      try {
        const [chars, trigs, inj, units] = await Promise.all([
          SupabaseService.getAllCharacters(),
          SupabaseService.getGlobalTriggers(),
          SupabaseService.getInjuries(),
          SupabaseService.getTimeUnits()
        ]);
        setCharacters(chars);
        setRosterList(chars);
        setTriggersMap(trigs);
        setInjuryDefinitions(inj);
        setTimeUnits(units);
      } catch (e) { console.error("Failed to init app", e); } finally { setIsLoadingData(false); }
    };
    init();
  }, []);

  const handleCreate = async () => {
    const newChar: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
    newChar.id = crypto.randomUUID();
    newChar.profile.name = "Новая Душа";
    if (user && !isAdmin) newChar.meta.uid = user.id;

    // Inject basic actions right away for new character, hidden by default
    const basicActions = await SupabaseService.getBasicActions();
    if (basicActions && basicActions.length > 0) {
        newChar.ability_groups = [{
            name: "Базовые Действия",
            tags: [],
            abilities: basicActions,
            is_hidden: true
        }];
    }

    const updated = [...characters, newChar];
    setCharacters(updated);
    setRosterList(updated);

    try {
      await SupabaseService.saveCharacter(newChar, isAdmin);
      setActiveCharId(newChar.id);
      setCharStack([newChar.id]);
      setView('sheet');
      setIsEditMode(true);
    } catch (e) {
      showAlert("Ошибка создания: " + e, "Сбой базы данных");
      const reverted = characters.filter(c => c.id !== newChar.id);
      setCharacters(reverted);
      setRosterList(reverted);
    }
  };

  const handleImportCharacter = async (file: File) => {
    try {
      const text = await file.text();
      const json = JSON.parse(text);
      if (!json.profile) throw new Error("Неверный формат JSON (нет profile)");

      const newChar: CharacterData = {
          ...json,
          id: crypto.randomUUID(), // Always new ID to avoid conflicts
          meta: {
              ...json.meta,
              uid: user?.id || 'guest', // Claim ownership
              save_status: true,
              master_id: json.meta?.master_id || undefined
          }
      };

      // Inject basic actions if missing
      const hasBasic = newChar.ability_groups?.some(g => g.name === "Базовые Действия");
      if (!hasBasic) {
          const basicActions = await SupabaseService.getBasicActions();
          if (basicActions && basicActions.length > 0) {
              if(!newChar.ability_groups) newChar.ability_groups = [];
              newChar.ability_groups.unshift({
                  name: "Базовые Действия",
                  tags: [],
                  abilities: basicActions,
                  is_hidden: true
              });
          }
      }

      await SupabaseService.saveCharacter(newChar, isAdmin);

      const updated = [...characters, newChar];
      setCharacters(updated);
      setRosterList(updated);

      setActiveCharId(newChar.id);
      setCharStack([newChar.id]);
      setView('sheet');
      setIsEditMode(false);
      showAlert("Персонаж успешно импортирован", "Успех");
    } catch (e: any) {
      showAlert("Ошибка импорта: " + e.message, "Ошибка");
    }
  };

  const handleSelect = (id: string) => {
    setActiveCharId(id);
    setCharStack([id]);
    setView('sheet');
    setIsEditMode(false);
    window.scrollTo(0,0);
  };

  const handleNavigateToUnit = (unitId: string) => {
    setCharStack(prev => [...prev, unitId]);
    setActiveCharId(unitId);
    window.scrollTo(0,0);
  };

  const handleBack = () => {
    if (charStack.length > 1) {
      const newStack = [...charStack];
      newStack.pop();
      setCharStack(newStack);
      setActiveCharId(newStack[newStack.length - 1]);
    } else {
      setView('roster');
      setActiveCharId(null);
      setCharStack([]);
    }
  };

  const handleNextTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const nextId = SHEET_TABS[(idx + 1) % SHEET_TABS.length].id;
      setActiveTab(nextId as any);
  };

  const handlePrevTab = () => {
      const idx = SHEET_TABS.findIndex(t => t.id === activeTab);
      const prevId = SHEET_TABS[(idx - 1 + SHEET_TABS.length) % SHEET_TABS.length].id;
      setActiveTab(prevId as any);
  };

  const activeChar = characters.find(c => c.id === activeCharId);
  const isOwner = user && activeChar && activeChar.meta.uid === user.id;
  const canEdit = isAdmin || isOwner;

  const updateActiveChar = (updates: Partial<CharacterData>) => {
    if (!activeChar) return;
    const updated = { ...activeChar, ...updates };
    setCharacters(prev => prev.map(c => c.id === activeChar.id ? updated : c));
  };

  const handleSave = async () => {
    if (!activeChar) return;
    try {
      await SupabaseService.saveCharacter(activeChar, isAdmin);
      setIsEditMode(false);
      setRosterList(characters);
    } catch (e) { showAlert("Ошибка сохранения: " + e, "Ошибка"); }
  };

  const handleInstantUpdate = async (eq: CharacterData['equipment']) => {
      if (!activeChar) return;
      const updated = { ...activeChar, equipment: eq };
      const newChars = characters.map(c => c.id === activeChar.id ? updated : c);
      setCharacters(newChars);
      await SupabaseService.saveCharacter(updated, isAdmin);
      setRosterList(newChars);
  };

  const handleDelete = async (idToDelete?: string) => {
    const targetId = idToDelete || activeChar?.id;
    if (!targetId) return;
    showConfirm("Вы уверены? Это действие необратимо уничтожит сущность.", async () => {
        try {
          await SupabaseService.deleteCharacter(targetId);
          const updated = characters.filter(c => c.id !== targetId);
          setCharacters(updated);
          setRosterList(updated);
          if (targetId === activeCharId) handleBack();
        } catch (e) { showAlert("Ошибка удаления: " + e, "Ошибка"); }
    }, "Уничтожение");
  };

  const createUnit = async () => {
      if (!activeChar) return;
      const unit: CharacterData = JSON.parse(JSON.stringify(INITIAL_CHARACTER));
      unit.id = crypto.randomUUID();
      unit.profile.name = "Новый Юнит";
      unit.meta.master_id = activeChar.id;
      unit.meta.uid = activeChar.meta.uid; 

      const basicActions = await SupabaseService.getBasicActions();
      if (basicActions && basicActions.length > 0) {
          unit.ability_groups = [{
              name: "Базовые Действия",
              tags: [],
              abilities: basicActions,
              is_hidden: true // Hidden by default
          }];
      }

      try {
        await SupabaseService.saveCharacter(unit, isAdmin);
        const updated = [...characters, unit];
        setCharacters(updated);
        setRosterList(updated);
        handleNavigateToUnit(unit.id);
        setIsEditMode(true);
      } catch (e) { showAlert("Cannot create unit: " + e, "Ошибка"); }
  };

  const getSheetBackground = (faction: Faction) => {
      if (faction === Faction.LIGHT) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Light_bg.jpg';
      if (faction === Faction.DARK) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Dark_bg.jpg';
      if (faction === Faction.NPC) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/Bestiary_bg.jpg';
      if (faction === Faction.GRAVEYARD) return 'https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/graveyard_bg.jpg';
      return null;
  };

  if (isLoadingData) {
    return (
      <div className="min-h-full flex items-center justify-center text-violet-500">
        <Loader2 size={48} className="animate-spin" />
      </div>
    );
  }

  if (view === 'training') return <TrainingPage characters={characters} onBack={() => setView('roster')} />;

  return (
    <div className="font-sans text-slate-300 selection:bg-violet-900/40 selection:text-white h-full relative">
      {view === 'sheet' && activeChar && (
          <>
            {getSheetBackground(activeChar.profile.faction) ? (
                <div className="fixed inset-0 z-0 overflow-hidden">
                    <div className="absolute inset-0 bg-cover bg-center bg-no-repeat bg-fixed blur-[5px] scale-105" style={{ backgroundImage: `url(${getSheetBackground(activeChar.profile.faction)})` }}></div>
                    <div className="absolute inset-0 bg-black/50"></div>
                </div>
            ) : ( <div className="fixed inset-0 bg-gradient-to-b from-slate-900 to-black z-0 pointer-events-none"></div> )}
          </>
      )}

      {view === 'roster' && (
        <>
          <Roster characters={rosterList} onSelect={handleSelect} onCreate={handleCreate} onImport={handleImportCharacter} onOpenSettings={() => setIsSettingsOpen(true)} onOpenTraining={() => setView('training')} />
          {isSettingsOpen && isAdmin && (
             <GlobalSettingsModal onClose={() => setIsSettingsOpen(false)} triggersMap={triggersMap} onSaveTriggers={async (t) => { await SupabaseService.saveGlobalTriggers(t); setTriggersMap(t); }} injuryDefinitions={injuryDefinitions} onSaveInjuries={async (inj) => { await SupabaseService.saveInjuries(inj); setInjuryDefinitions(inj); }} timeUnits={timeUnits} onSaveTimeUnits={async (units) => { await SupabaseService.saveTimeUnits(units); setTimeUnits(units); }} />
          )}
        </>
      )}

      {view === 'sheet' && activeChar && (
        <div className="relative z-10 max-w-5xl mx-auto p-4 md:p-6 animate-fade-in pb-32">
          <div className="flex items-center justify-between mb-6 bg-[#020617]/80 backdrop-blur-md p-3 border-b border-violet-900/30 sticky top-12 min-[1150px]:top-0 z-50 shadow-lg rune-clip-r">
            <div className="flex items-center gap-2">
               <Button variant="secondary" size="sm" onClick={handleBack} className="bg-[#0f172a] border-slate-700 hover:bg-slate-800 text-slate-200 hover:text-white shadow-md z-10 font-serif tracking-wide">
                 <ChevronLeft size={18} /> {t('act_back', "Назад")}
               </Button>
               {charStack.length > 1 && ( <span className="text-xs text-slate-500 font-serif uppercase tracking-wider hidden md:inline ml-2 border-l border-slate-700 pl-3"> {t('lbl_depth', 'Глубина')}: {charStack.length} </span> )}
            </div>
            <div className="flex items-center gap-2">
               {isDialectUnlocked && ( <button onClick={toggleDialect} className={`p-2 rounded border transition-all ${isOldSlavonic ? 'bg-amber-900/20 text-amber-500 border-amber-800' : 'bg-slate-800 text-slate-500 border-slate-700'}`} title="Old Slavonic Dialect"> <ScrollText size={18} /> </button> )}
               <div className="h-6 w-px bg-slate-800 mx-1"></div>
               <div className="flex bg-[#0f172a] p-1 rounded-sm border border-slate-800">
                  <button onClick={() => setDisplayMode('lore')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'lore' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Lore Mode"> <BookOpen size={16} /> </button>
                  <button onClick={() => setDisplayMode('mech')} className={`p-1.5 rounded-sm transition-all ${displayMode === 'mech' ? 'bg-violet-900/50 text-violet-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="Mechanic Mode"> <Calculator size={16} /> </button>
               </div>

               {/* Tag Hints - Visible to All */}
               <button onClick={() => setIsTagHintsOpen(true)} className="p-2 text-slate-500 hover:text-violet-300 transition-colors ml-1" title="Справочник Тегов"> <Tag size={18} /> </button>

               {canEdit && (
                 <>
                   <div className="h-6 w-px bg-slate-800 mx-1"></div>
                   {isEditMode ? (
                     <>
                        {isAdmin && ( <Button variant="danger" size="sm" onClick={() => handleDelete(activeChar.id)} title="Delete"> <Trash2 size={16} /> </Button> )}
                        <Button variant="secondary" size="sm" onClick={() => { showConfirm("Отменить несохраненные изменения?", () => { const original = rosterList.find(c => c.id === activeChar.id); if (original) updateActiveChar(original); setIsEditMode(false); }); }}> <RotateCcw size={16} /> </Button>
                        <Button className="bg-emerald-900/80 hover:bg-emerald-800 border-emerald-500/50" size="sm" onClick={handleSave}> <Save size={16} /> {t('act_save', "Сохранить")} </Button>
                     </>
                   ) : ( <Button variant="secondary" size="sm" onClick={() => setIsEditMode(true)}> <Edit3 size={16} /> {t('act_edit', "Ред.")} </Button> )}
                 </>
               )}
            </div>
          </div>

          <SheetHeader character={activeChar} isEditMode={isEditMode} onChange={updateActiveChar} displayMode={displayMode} setDisplayMode={setDisplayMode} characters={characters} onNavigate={handleNavigateToUnit} onDelete={isAdmin ? handleDelete : undefined} injuryDefinitions={injuryDefinitions} />

          <div className="hidden md:flex sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 px-0 md:px-0">
             <div className="flex overflow-x-auto no-scrollbar gap-1 pb-1">
                {SHEET_TABS.map(tab => (
                  <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-6 py-3 text-sm font-serif font-bold uppercase tracking-widest transition-all whitespace-nowrap relative group flex-shrink-0 ${ activeTab === tab.id ? 'text-violet-300' : 'text-slate-600 hover:text-slate-300' }`} >
                    {tab.label}
                    {activeTab === tab.id && ( <div className="absolute bottom-0 left-0 w-full h-0.5 bg-violet-500 shadow-[0_0_10px_#8b5cf6]"></div> )}
                  </button>
                ))}
             </div>
          </div>

          <div className="md:hidden sticky top-28 min-[1150px]:top-14 z-40 bg-[#020617]/95 backdrop-blur-md border-b border-violet-900/30 mb-6 -mx-4 px-4 py-2 flex items-center justify-between">
              <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronLeft size={24} /> </button>
              <div className="font-serif font-bold uppercase tracking-widest text-violet-300 text-sm"> {SHEET_TABS.find(t => t.id === activeTab)?.label} </div>
              <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors"> <ChevronRight size={24} /> </button>
          </div>

          <div>
            {activeTab === 'equipment' && ( <TabEquipment character={activeChar} isEditMode={isEditMode} onChange={(eq) => updateActiveChar({ equipment: eq })} displayMode={displayMode} onInstantUpdate={(eq) => handleInstantUpdate(eq)} /> )}
            {activeTab === 'abilities' && ( <TabAbilities character={activeChar} isEditMode={isEditMode} onChange={(groups) => updateActiveChar({ ability_groups: groups })} displayMode={displayMode} timeUnits={timeUnits} onCharacterUpdate={updateActiveChar} /> )}
            {activeTab === 'passives' && ( <TabPassives character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} onCharacterUpdate={updateActiveChar} /> )}
            {activeTab === 'debuffs' && ( <TabDebuffs character={activeChar} isEditMode={isEditMode} onChange={(p) => updateActiveChar({ passives: p })} displayMode={displayMode} triggersMap={triggersMap} timeUnits={timeUnits} onCharacterUpdate={updateActiveChar} /> )}
            {activeTab === 'units' && ( <TabUnits master={activeChar} units={characters} onCreateUnit={createUnit} onNavigateToUnit={handleNavigateToUnit} isEditMode={isEditMode} /> )}
            {activeTab === 'medcard' && ( <TabMedCard character={activeChar} isEditMode={isEditMode} onChange={(mc) => updateActiveChar({ medcard: mc })} injuryDefinitions={injuryDefinitions} /> )}
          </div>
        </div>
      )}

      {isTagHintsOpen && ( <TagHintsModal isOpen={isTagHintsOpen} onClose={() => setIsTagHintsOpen(false)} isAdmin={isAdmin} /> )}
    </div>
  );
};

export const RosterAdminContainer: React.FC = () => { return null; };
const RosterModule: React.FC<RosterModuleProps> = (props) => ( <DialectProvider> <UIProvider> <RosterContent {...props} /> </UIProvider> </DialectProvider> );
export default RosterModule;
